svg.script:
(function () {
  var CELL = 17, COLS = 20, ROWS = 20;
  var snakeG = document.getElementById('snake');
  var foodG = document.getElementById('food');
  var scoreT = document.getElementById('score');
  var overlay = document.getElementById('overlay');
  var snake, dir, nextDir, food, score, running, gameOver, timer, started;

  // —— retention + contact (shared pattern) ——
  var GAME = 'snake', DAILY_TARGET = 200;
  var DAILY_GAMES = ['snake', '2048', 'pong', 'abtest', 'funnel', 'cohort', 'sql', 'metric', 'retention', 'bottleneck'];
  var LS_BEST = 'arcade_best_' + GAME;
  var cta = document.getElementById('cta');
  var IS_LOCAL = /^(localhost|127\.0\.0\.1|::1|0\.0\.0\.0)$/.test(window.location.hostname);
  var PH_KEY = 'phc_tdju2w288PnkFE2e96efWKpoCvBPHPtveSztZK9NnGrv';
  if (!IS_LOCAL && PH_KEY.indexOf('__PH_') !== 0 && !window.posthog) {
    try {
      var phs = document.createElementNS('http://www.w3.org/2000/svg', 'script');
      phs.setAttribute('href', 'https://us-assets.i.posthog.com/static/array.js');
      phs.setAttribute('type', 'text/javascript');
      phs.onload = function () { try { window.posthog.init(PH_KEY, { defaults: '2026-05-30', persistence: 'localStorage+cookie', api_host: 'https://us.i.posthog.com', capture_pageview: true, capture_pageleave: true, autocapture: true, capture_exceptions: true, session_recording: { maskAllInputs: true } }); } catch (e) {} };
      document.documentElement.appendChild(phs);
    } catch (e) {}
  }
  function ph(name, props) { try { if (window.posthog && window.posthog.capture) window.posthog.capture(name, props || {}); } catch (e) {} }
  function lsGet(k, d) { try { var v = localStorage.getItem(k); return v === null ? d : v; } catch (e) { return d; } }
  function lsSet(k, v) { try { localStorage.setItem(k, v); } catch (e) {} }
  function bestOf() { return parseInt(lsGet(LS_BEST, '0'), 10) || 0; }
  function todayStr() { var n = new Date(); return n.getFullYear() + '-' + ('0' + (n.getMonth() + 1)).slice(-2) + '-' + ('0' + n.getDate()).slice(-2); }
  function todayGame() { return DAILY_GAMES[Math.floor(Date.now() / 86400000) % DAILY_GAMES.length]; }
  function markDaily() {
    var t = todayStr();
    var y = new Date(); y.setDate(y.getDate() - 1);
    var yst = y.getFullYear() + '-' + ('0' + (y.getMonth() + 1)).slice(-2) + '-' + ('0' + y.getDate()).slice(-2);
    var streak = lsGet('arcade_daily_date', '') === yst ? (parseInt(lsGet('arcade_streak', '0'), 10) || 0) + 1 : 1;
    lsSet('arcade_daily_date', t); lsSet('arcade_daily_done', '1'); lsSet('arcade_streak', String(streak));
    ph('daily_completed', { game: GAME, streak: streak });
  }
  function showCTA(on) { if (cta) cta.style.display = on ? 'block' : 'none'; }
  function wireCTA() {
    if (!cta) return;
    var links = cta.querySelectorAll('a');
    for (var i = 0; i < links.length; i++) {
      links[i].addEventListener('click', function () {
        var href = this.getAttribute('href') || '';
        var channel = href.indexOf('linkedin') !== -1 ? 'linkedin' : (href.indexOf('t.me') !== -1 ? 'telegram' : 'other');
        ph('contact_click', { location: 'game_over', channel: channel, game: GAME });
      });
    }
  }
  // —— /retention ——

  function begin() {
    if (!running && !gameOver) {
      running = true;
      overlay.textContent = '';
      if (!started) { started = true; ph('game_started', { game: GAME }); }
      timer = setInterval(step, 120);
    }
  }

  function init() {
    snake = [{x:10,y:10},{x:9,y:10},{x:8,y:10}];
    dir = {x:1,y:0}; nextDir = {x:1,y:0};
    score = 0; running = false; gameOver = false;
    started = false;
    if (timer) { clearInterval(timer); timer = null; }
    placeFood();
    draw();
    scoreT.textContent = 'Score: 0 · Best: ' + bestOf();
    overlay.textContent = 'Press any arrow key to start';
    overlay.setAttribute('fill', '#f4f4f5');
    showCTA(false);
  }

  function placeFood() {
    do {
      food = {x: Math.floor(Math.random()*COLS), y: Math.floor(Math.random()*ROWS)};
    } while (snake.some(function (s) { return s.x === food.x && s.y === food.y; }));
  }

  function draw() {
    while (snakeG.firstChild) snakeG.removeChild(snakeG.firstChild);
    while (foodG.firstChild) foodG.removeChild(foodG.firstChild);
    for (var i = 0; i < snake.length; i++) {
      var r = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
      r.setAttribute('x', snake[i].x*CELL + 1);
      r.setAttribute('y', snake[i].y*CELL + 1);
      r.setAttribute('width', CELL - 2);
      r.setAttribute('height', CELL - 2);
      r.setAttribute('rx', 3);
      r.setAttribute('fill', i === 0 ? '#ff6643' : '#8a2e15');
      snakeG.appendChild(r);
    }
    var f = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
    f.setAttribute('x', food.x*CELL + 1);
    f.setAttribute('y', food.y*CELL + 1);
    f.setAttribute('width', CELL - 2);
    f.setAttribute('height', CELL - 2);
    f.setAttribute('rx', 3);
    f.setAttribute('fill', '#ff4b4b');
    foodG.appendChild(f);
  }

  function step() {
    dir = nextDir;
    var head = {x: snake[0].x + dir.x, y: snake[0].y + dir.y};
    if (head.x < 0 || head.x >= COLS || head.y < 0 || head.y >= ROWS) { endGame(); return; }
    for (var i = 0; i < snake.length; i++) {
      if (snake[i].x === head.x && snake[i].y === head.y) { endGame(); return; }
    }
    snake.unshift(head);
    if (head.x === food.x && head.y === food.y) {
      score += 10;
      scoreT.textContent = 'Score: ' + score + ' · Best: ' + Math.max(bestOf(), score);
      placeFood();
    } else {
      snake.pop();
    }
    draw();
  }

  function endGame() {
    running = false; gameOver = true;
    if (timer) { clearInterval(timer); timer = null; }
    var best = bestOf();
    var newBest = score > best;
    if (newBest) { lsSet(LS_BEST, String(score)); ph('best_broken', { game: GAME, old_best: best, new_best: score, score: score }); }
    var isDaily = todayGame() === GAME && score >= DAILY_TARGET;
    if (isDaily) markDaily();
    showCTA(newBest);
    overlay.textContent = (newBest ? 'NEW BEST! ' : 'Game over — Score: ') + score + '. Press R to restart';
    overlay.setAttribute('fill', newBest ? '#4ade80' : '#ff4b4b');
    ph('game_over', { game: GAME, score: score, new_best: newBest, daily_done: !!isDaily });
  }

  document.addEventListener('keydown', function (e) {
    var k = e.key;
    if (k === 'ArrowUp' || k === 'w' || k === 'W') { if (dir.y !== 1) nextDir = {x:0,y:-1}; e.preventDefault(); }
    else if (k === 'ArrowDown' || k === 's' || k === 'S') { if (dir.y !== -1) nextDir = {x:0,y:1}; e.preventDefault(); }
    else if (k === 'ArrowLeft' || k === 'a' || k === 'A') { if (dir.x !== 1) nextDir = {x:-1,y:0}; e.preventDefault(); }
    else if (k === 'ArrowRight' || k === 'd' || k === 'D') { if (dir.x !== -1) nextDir = {x:1,y:0}; e.preventDefault(); }
    else if (k === 'r' || k === 'R') { init(); return; }
    begin();
  });

  // --- Touch controls (mobile) ---
  var tsx = 0, tsy = 0;
  function setDir(nx, ny) {
    if (nx === 0 && ny === -1) { if (dir.y !== 1) nextDir = {x: 0, y: -1}; }
    else if (nx === 0 && ny === 1) { if (dir.y !== -1) nextDir = {x: 0, y: 1}; }
    else if (nx === -1 && ny === 0) { if (dir.x !== 1) nextDir = {x: -1, y: 0}; }
    else if (nx === 1 && ny === 0) { if (dir.x !== -1) nextDir = {x: 1, y: 0}; }
  }
  document.addEventListener('touchstart', function (e) { tsx = e.touches[0].clientX; tsy = e.touches[0].clientY; }, {passive: true});
  document.addEventListener('touchmove', function (e) { e.preventDefault(); }, {passive: false});
  document.addEventListener('touchend', function (e) {
    var t = e.changedTouches[0];
    var dx = t.clientX - tsx, dy = t.clientY - tsy;
    if (Math.abs(dx) < 24 && Math.abs(dy) < 24) {
      if (gameOver) { init(); return; }
      begin(); return;
    }
    if (Math.abs(dx) > Math.abs(dy)) setDir(dx > 0 ? 1 : -1, 0);
    else setDir(0, dy > 0 ? 1 : -1);
    begin();
  }, {passive: false});

  wireCTA();
  init();
})();
